import assert from 'node:assert/strict';import Worker from '../dist/server/index.js';import {fixture} from './friend-server.mjs';const f=fixture();let code;async function call(path,body){const r=await Worker.fetch(new Request('https://quota.test'+path,{method:'POST',headers:{'CF-Connecting-IP':'192.0.2.1','Content-Type':'application/json'},body:JSON.stringify(body)}),f.env);const value=await r.json();return {status:r.status,value};}try{const states={};for(let i=0;i<121;i++){const r=await call('/api/guest',{});states[r.status]=(states[r.status]||0)+1;if(!code)code=r.value.recoveryCode;}assert.deepEqual(states,{'200':120,'429':1});const restores={};for(let i=0;i<21;i++){const r=await call('/api/guest/restore',{recoveryCode:code});restores[r.status]=(restores[r.status]||0)+1;}assert.deepEqual(restores,{'200':20,'429':1});console.log(JSON.stringify({sharedIPCreate:states,sharedIPRestore:restores,window:'60s',note:'same external IP, new guest creation and recovery only; existing sessions unaffected'}));}finally{f.sqlite.close();}
